import{z as c,x as i,o,c as d,q as s,j as t,D as e,d as n,s as E,S as p}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"namespace 与 cgroup 的深化","description":"","frontmatter":{"title":"namespace 与 cgroup 的深化","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/virt-ns-cgroup-deep.md","filePath":"cs/virt-ns-cgroup-deep.md","lastUpdated":1791063341000}'),l={name:"cs/virt-ns-cgroup-deep.md"};function m(A,a,u,B,h,g){const r=i("Mermaid");return o(),d("div",null,[a[2]||(a[2]=s('<h1 id="namespace-与-cgroup-的深化" tabindex="-1">namespace 与 cgroup 的深化 <a class="header-anchor" href="#namespace-与-cgroup-的深化" aria-label="Permalink to &quot;namespace 与 cgroup 的深化&quot;">​</a></h1><div class="epigraph"><p>namespace 回答「你看见什么」，cgroup 回答「你能拿多少」；前者隔离名字，后者隔离预算，两者都发生在同一个内核里，没有第二道特权环。</p><footer>—— 据 Linux namespaces(7) 与 cgroup v2 内核文档整理</footer></div><p><a href="/cs/virt-container-runtime">上一课</a>说明运行时只是把 JSON 里的隔离参数写进内核。本课拆开这两类参数本身：主干课<a href="/cs/namespaces">namespaces</a>与<a href="/cs/cgroups">cgroups</a>给过 clone 标志与记账的直觉，本课补工程里真正咬人的三处——命名空间的生命周期、user namespace 的映射语义、以及配额文件之间被普遍读错的差别。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>命名空间的生命周期是「最后一个引用消失才销毁」，引用不止进程：打开 <code>/proc/&lt;pid&gt;/ns/net</code> 得到的 fd 也算。于是有运维里最常见的幽灵：容器里进程全退了，网络栈却还在——某个句柄（转发的 fd、<code>setns</code> 工具、挂起的 veth 对端）把 netns 钉住了。卡在里面的设备、路由与 conntrack 继续占内存，<code>ip netns list</code> 却看不见它。第二个缺口是权限：容器内 uid 0 是谁的 root？user namespace 的回答是<strong>映射</strong>——<code>uid_map</code> 写着「内的 0 对应外的 100000」这样的区间表；而 capabilities 是<strong>相对于拥有资源的那个 user namespace</strong> 判定的：容器 root 对自己 ns 里的文件是 root，对宿主设备仍然什么都不是。rootless 容器整个立在这条语义上。</p>',5)),(o(),t(p,null,{default:e(()=>[E(r,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E5%AE%B9%E5%99%A8%E8%BF%9B%E7%A8%8B%E5%85%A8%E9%83%A8%E9%80%80%E5%87%BA%22%5D%20--%3E%20REF%7B%22netns%20%E8%BF%98%E6%9C%89%E5%88%AB%E7%9A%84%E5%BC%95%E7%94%A8%E5%90%97%22%7D%0A%20%20REF%20--%3E%7C%22veth%20%E5%AF%B9%E7%AB%AF%E4%BB%8D%E6%8C%82%E7%9D%80%22%7C%20PIN%5B%22netns%20%E8%A2%AB%E9%92%89%E4%BD%8F%22%5D%0A%20%20REF%20--%3E%7C%22%E8%BD%AC%E5%8F%91%E7%9A%84%20fd%20%E6%9C%AA%E5%85%B3%22%7C%20PIN%0A%20%20REF%20--%3E%7C%22setns%20%E5%B7%A5%E5%85%B7%E6%8C%81%E5%8F%A5%E6%9F%84%22%7C%20PIN%0A%20%20PIN%20--%3E%20GHOST%5B%22%E8%AE%BE%E5%A4%87%2C%20%E8%B7%AF%E7%94%B1%E4%B8%8E%20conntrack%20%E4%BB%8D%E8%AE%B0%E8%B4%A6%22%5D%0A%20%20GHOST%20--%3E%20INVIS%5B%22ip%20netns%20list%20%E7%9C%8B%E4%B8%8D%E8%A7%81%E7%9A%84%E5%B9%BD%E7%81%B5%22%5D%0A%20%20REF%20--%3E%7C%22%E6%97%A0%E4%BB%BB%E4%BD%95%E5%BC%95%E7%94%A8%22%7C%20FREE%5B%22netns%20%E9%94%80%E6%AF%81%2C%20%E8%B5%84%E6%BA%90%E5%BD%92%E8%BF%98%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s('<p><span class="marginnote">数字实例：uid_map 写着「0 100000 65536」——容器内的 0 到 65535 这一段，逐个映射到宿主的 100000 到 165535；于是容器里的 root 对自家文件是真 root，对宿主却只是个编号十万开外的普通用户，这正是 rootless 容器的地基。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法是把参数读成语义而不是默认值：生命周期看引用，权限看映射，配额看文件的语义差别。</p><h3 id="预算文件的两个常见误读" tabindex="-1">预算文件的两个常见误读 <a class="header-anchor" href="#预算文件的两个常见误读" aria-label="Permalink to &quot;预算文件的两个常见误读&quot;">​</a></h3><p>内存侧：<code>memory.max</code> 是硬顶，顶到就触发组内 <a href="/cs/oom-killer">OOM</a>；<code>memory.high</code> 是节流线，超过就压制分配、逼回收，把「抖动」换掉「击杀」。用 max 做软预算的应用会在流量尖峰被 OOM 杀掉，而这本是 high 该接住的形状。CPU 侧：<code>cpu.max</code> 的语义是「每 period 窗口最多 quota」——一百毫秒窗口里用完五十毫秒配额，组内<strong>所有</strong>线程立刻被冻到窗口结束。多线程应用在尖峰期整组卡顿、尾部延迟翻倍，常常不是 CPU 不够，而是配额窗口被早早烧完；要「多用但让路」应该用 <code>cpu.weight</code>，那才是权重语义。</p><p><span class="marginnote">数字实例：cpu.max 写「50000 100000」意思是每 100 毫秒窗口最多用 50 毫秒；16 个线程的进程可能在第 50 毫秒就把全组配额烧完，剩下 50 毫秒所有线程集体冻结——尖峰期尾延迟翻倍，查的常常不是 CPU 够不够，而是窗口有没有被烧穿。</span></p>',6)),(o(),t(p,null,{default:e(()=>[E(r,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20CFG%5B%22%E8%BF%90%E8%A1%8C%E6%97%B6%E9%85%8D%E7%BD%AE%22%5D%20--%3E%20NS%5B%22namespace%3A%20%E8%A7%86%E5%9B%BE%22%5D%0A%20%20CFG%20--%3E%20CG%5B%22cgroup%3A%20%E9%A2%84%E7%AE%97%22%5D%0A%20%20NS%20--%3E%20USERNS%5B%22user%20ns%3A%20uid%20%E6%98%A0%E5%B0%84%E5%AE%9A%E6%9D%83%E9%99%90%22%5D%0A%20%20CG%20--%3E%20MEM%5B%22memory.high%20%E8%8A%82%E6%B5%81%20%2F%20memory.max%20%E5%87%BB%E6%9D%80%22%5D%0A%20%20CG%20--%3E%20CPU%5B%22cpu.max%20%E7%AA%97%E5%8F%A3%E9%85%8D%E9%A2%9D%20%2F%20cpu.weight%20%E6%9D%83%E9%87%8D%22%5D%0A%20%20USERNS%20--%3E%20K%5B%22%E5%90%8C%E4%B8%80%E4%B8%AA%E5%86%85%E6%A0%B8%22%5D%0A%20%20MEM%20--%3E%20K%0A%20%20CPU%20--%3E%20K%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=s('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>把两类原语放回同一条轴看：虚拟机复制机器，靠第二套特权级与 EPT 把客户的越权变成陷入；namespace 与 cgroup 不复制任何机器——它们是同一内核的<strong>多份视图与多本账簿</strong>，切换视图只是一次查表换参数，没有陷入可省。这就是容器密度高的机制来源，也是它的边界来源：视图切得再细，系统调用仍然通到同一份代码，预算锁得再死，记账 bug 仍然是全局的。cgroup v2 的统一层级与「进程只在叶子」约束、子树的委派，都是在让「多本账簿」可以安全地交给非特权用户管——委派的是记账权，不是越权通道。</p><p><span class="marginnote">直觉类比：虚拟机是复制一栋楼，各有各的门卫与楼梯；namespace 是同一栋楼发给不同租户不同的门牌与钥匙，cgroup 是按户装的水电表。换视图只是换钥匙，进的仍是同一栋楼——所以没有陷入可省，密度才高，边界也才薄。</span></p><p><span class="marginnote">两个易错点：pid namespace 里容器 init 退出即全组处决——init 死，组内其余进程收到不可捕获、不可忽略的信号；而 /proc 挂载若用了宿主的 procfs，pid 视图与挂载视图错位，容器内 ps 会看见宿主全表。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 time 与 cgroup namespace 的全部细节，也不写逃逸路径——共享内核的越权面归<a href="/cs/virt-security-boundary">安全边界</a>，容器攻防另有主干课收口。io 控制器的成本模型（iocost）与内存水位和页缓存回收的交互，需要在<a href="/cs/anon-vs-file-page">匿名页对文件页</a>的框架里另算，本课只钉「max 与 high 语义不同」。还有一个边界要说破：user namespace 的映射让容器内 root 失去对外特权，但它同时扩大了内核攻击面——攻击者不必再是 root 才能碰到 user namespace 相关代码，这道两难在安全课里重新计价。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>namespace 管视图，cgroup 管预算；两者都在同一内核内，无第二特权环。</li><li>命名空间生命周期随最后一个引用（含 fd）消失，fd 钉住的 netns 是常见幽灵资源。</li><li>user namespace 用 uid 映射收缩容器 root 的含义，capabilities 按拥有资源的 ns 判定。</li><li>memory.max 硬顶杀进程，memory.high 节流；cpu.max 是窗口配额，尖峰烧完即全组冻结。</li><li>出处：据 Linux namespaces(7)、cgroup v2 内核文档整理。</li></ul>',8))])}const D=c(l,[["render",m]]);export{C as __pageData,D as default};
